// Carriers re-send delivery events, sometimes days apart. The order id is
// the idempotency key: the sheet append below is keyed on it, and the daily
// sweep skips anything already marked sent. Without this the same customer
// gets asked three times and unsubscribes.
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const orderId = String(b.order_id ?? '').trim();
  const email = String(b.email ?? '').trim().toLowerCase();
  if (!orderId || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) continue;
  if (String(b.status ?? '').toLowerCase() !== 'delivered') continue;
  // Ask after the customer has actually used the product, not the day it lands.
  const WAIT_DAYS = 7;
  const sendAfter = new Date(Date.now() + WAIT_DAYS * 864e5);
  out.push({ json: {
    orderId,
    email,
    firstName: String(b.first_name ?? '').trim(),
    product: String(b.product ?? '').trim(),
    timezone: String(b.timezone ?? 'Europe/London').trim(),
    deliveredAt: new Date().toISOString(),
    sendAfter: sendAfter.toISOString().slice(0, 10),
    status: 'pending'
  }});
}
return out;

// Four independent reasons not to send. Each one is a real complaint if you
// get it wrong, so they are checked explicitly rather than folded into one
// clever condition.
const queue = $('Read queue').all().map(i => i.json);
const suppressed = new Set(
  $('Read suppression list').all()
    .map(i => String(i.json.email ?? '').trim().toLowerCase())
    .filter(Boolean)
);
const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const row of queue) {
  const email = String(row.email ?? '').trim().toLowerCase();
  if (!email) continue;
  if (String(row.status ?? '') !== 'pending') continue;      // 1. already sent
  if (suppressed.has(email)) continue;                        // 2. unsubscribed, or already reviewed
  if (String(row.sendAfter ?? '') > today) continue;          // 3. still inside the wait
  // 4. Send inside the recipient's waking hours. Their timezone, not ours.
  let localHour;
  try {
    localHour = Number(new Intl.DateTimeFormat('en-GB', {
      hour: 'numeric', hour12: false, timeZone: row.timezone || 'Europe/London'
    }).format(new Date()));
  } catch (e) {
    localHour = 10; // unknown timezone: treat as sendable rather than stranding the row forever
  }
  if (localHour < 9 || localHour > 18) continue;
  out.push({ json: { ...row, email } });
}
return out;
